"use server";

import { prisma } from "@/lib/prisma";
import { runDuplicateDetection } from "@/lib/duplicateEngine";

export interface VoterApplicationInput {
    fullName: string;
    dateOfBirth: string; // YYYY-MM-DD
    gender: string;
    address: string;
    pincode: string;
    email: string;
    mobile: string;
}

export async function submitVoterApplication(input: VoterApplicationInput) {
    try {
        // Input validation
        if (!input.fullName.trim() || !input.dateOfBirth || !input.address.trim()) {
            return { success: false, error: "Please fill in all required personal details." };
        }
        if (!input.email.includes("@")) {
            return { success: false, error: "Please provide a valid email address." };
        }
        if (!/^\d{6}$/.test(input.pincode.trim())) {
            return { success: false, error: "Please enter a valid 6-digit postal pincode." };
        }

        // Check if exact same application number or duplicate email already has an active pending app
        const existingActive = await prisma.voterApplication.findFirst({
            where: {
                email: input.email.trim().toLowerCase(),
                status: { in: ["PENDING", "FLAGGED_DUPLICATE"] },
            },
        });

        if (existingActive) {
            return {
                success: false,
                error: `An active application (${existingActive.applicationNumber}) already exists for this email address. Please track your existing application status.`,
            };
        }

        // Generate unique Application Number
        const randomNum = Math.floor(10000 + Math.random() * 90000);
        const applicationNumber = `VOT-2026-${randomNum}`;

        // Execute Duplicate Detection Engine
        const dupResult = await runDuplicateDetection({
            fullName: input.fullName,
            dateOfBirth: input.dateOfBirth,
            gender: input.gender,
            address: input.address,
            pincode: input.pincode,
            email: input.email,
            mobile: input.mobile,
        });

        const status = dupResult.isDuplicateFlagged ? "FLAGGED_DUPLICATE" : "PENDING";
        const dobDate = new Date(input.dateOfBirth);

        // Create VoterApplication in database
        const newApp = await prisma.voterApplication.create({
            data: {
                applicationNumber,
                fullName: input.fullName.trim(),
                dateOfBirth: dobDate,
                gender: input.gender,
                address: input.address.trim(),
                pincode: input.pincode.trim(),
                email: input.email.trim().toLowerCase(),
                mobile: input.mobile.trim(),
                status,
                duplicateScore: dupResult.highestMatchScore,
            },
        });

        // Create Audit Log & DuplicateFlag if potential match detected
        if (dupResult.isDuplicateFlagged && dupResult.fieldBreakdown) {
            await prisma.duplicateFlag.create({
                data: {
                    applicationId: newApp.id,
                    matchedVoterId: dupResult.matchedVoterId || null,
                    matchedVoterName: dupResult.matchedVoterName || "Existing Record",
                    matchedVoterDetails: dupResult.matchedVoterDetails || {},
                    overallScore: dupResult.highestMatchScore,
                    fieldBreakdown: dupResult.fieldBreakdown as any,
                },
            });

            await prisma.auditLog.create({
                data: {
                    applicationId: newApp.id,
                    action: "FLAGGED_POTENTIAL_DUPLICATE",
                    performedBy: "SYSTEM_DUPLICATE_ENGINE",
                    notes: `Application flagged with ${dupResult.highestMatchScore}% similarity score to existing voter (${dupResult.matchedVoterName}). Routed to human electoral officer for review.`,
                },
            });
        } else {
            await prisma.auditLog.create({
                data: {
                    applicationId: newApp.id,
                    action: "SUBMITTED",
                    performedBy: "SYSTEM",
                    notes: "Voter application received successfully. Queued for standard verification.",
                },
            });
        }

        return {
            success: true,
            applicationNumber,
            status,
            isDuplicateFlagged: dupResult.isDuplicateFlagged,
            matchScore: dupResult.highestMatchScore,
        };
    } catch (error) {
        console.error("Error submitting voter application:", error);
        return { success: false, error: "Failed to submit voter application. Please try again." };
    }
}

export async function trackApplication(queryInput: string) {
    const query = queryInput.trim();
    if (!query) {
        return { success: false, error: "Please enter an application number or email." };
    }

    try {
        const app = await prisma.voterApplication.findFirst({
            where: {
                OR: [
                    { applicationNumber: { equals: query, mode: "insensitive" } },
                    { email: { equals: query, mode: "insensitive" } },
                ],
            },
            include: {
                flags: true,
                auditLogs: {
                    orderBy: { createdAt: "asc" },
                },
            },
        });

        if (!app) {
            return { success: false, error: "No voter application found matching your details." };
        }

        // Check if an official voter ID was generated
        const approvedVoter = await prisma.voter.findFirst({
            where: { email: app.email },
        });

        return {
            success: true,
            application: {
                id: app.id,
                applicationNumber: app.applicationNumber,
                fullName: app.fullName,
                dateOfBirth: app.dateOfBirth.toISOString().split("T")[0],
                gender: app.gender,
                address: app.address,
                pincode: app.pincode,
                email: app.email,
                mobile: app.mobile,
                status: app.status,
                duplicateScore: app.duplicateScore,
                createdAt: app.createdAt.toISOString(),
                voterIdNumber: approvedVoter?.voterIdNumber || null,
                flags: app.flags,
                auditLogs: app.auditLogs.map((log) => ({
                    id: log.id,
                    action: log.action,
                    performedBy: log.performedBy,
                    notes: log.notes,
                    createdAt: log.createdAt.toISOString(),
                })),
            },
        };
    } catch (error) {
        console.error("Error tracking application:", error);
        return { success: false, error: "Failed to retrieve application status." };
    }
}

export async function getAdminDashboardData() {
    try {
        const totalApplications = await prisma.voterApplication.count();
        const pendingCount = await prisma.voterApplication.count({
            where: { status: "PENDING" },
        });
        const flaggedCount = await prisma.voterApplication.count({
            where: { status: "FLAGGED_DUPLICATE" },
        });
        const approvedCount = await prisma.voterApplication.count({
            where: { status: "APPROVED" },
        });
        const rejectedCount = await prisma.voterApplication.count({
            where: { status: "REJECTED" },
        });
        const totalVoters = await prisma.voter.count();

        const applications = await prisma.voterApplication.findMany({
            orderBy: { createdAt: "desc" },
            include: {
                flags: true,
                auditLogs: {
                    orderBy: { createdAt: "desc" },
                    take: 1,
                },
            },
        });

        const auditLogs = await prisma.auditLog.findMany({
            orderBy: { createdAt: "desc" },
            take: 20,
            include: {
                application: {
                    select: {
                        applicationNumber: true,
                        fullName: true,
                    },
                },
            },
        });

        return {
            success: true,
            metrics: {
                totalApplications,
                pendingCount,
                flaggedCount,
                approvedCount,
                rejectedCount,
                totalVoters,
            },
            applications: applications.map((app) => ({
                id: app.id,
                applicationNumber: app.applicationNumber,
                fullName: app.fullName,
                dateOfBirth: app.dateOfBirth.toISOString().split("T")[0],
                gender: app.gender,
                address: app.address,
                pincode: app.pincode,
                email: app.email,
                mobile: app.mobile,
                status: app.status,
                duplicateScore: app.duplicateScore,
                createdAt: app.createdAt.toISOString(),
                flags: app.flags,
            })),
            auditLogs: auditLogs.map((log) => ({
                id: log.id,
                applicationNumber: log.application.applicationNumber,
                applicantName: log.application.fullName,
                action: log.action,
                performedBy: log.performedBy,
                notes: log.notes,
                createdAt: log.createdAt.toISOString(),
            })),
        };
    } catch (error) {
        console.error("Error fetching admin dashboard data:", error);
        return { success: false, error: "Failed to fetch admin data." };
    }
}

export async function reviewApplication({
    applicationId,
    decision,
    officerNotes,
    officerName,
}: {
    applicationId: string;
    decision: "APPROVED" | "REJECTED";
    officerNotes?: string;
    officerName?: string;
}) {
    try {
        const app = await prisma.voterApplication.findUnique({
            where: { id: applicationId },
        });

        if (!app) {
            return { success: false, error: "Application not found." };
        }

        const reviewer = officerName?.trim() || "Electoral Officer";
        const notes = officerNotes?.trim() || (decision === "APPROVED" ? "Verified and approved by officer." : "Rejected during manual review.");

        if (decision === "APPROVED") {
            const randomNum = Math.floor(100000 + Math.random() * 900000);
            const voterIdNumber = `VID-2026-${randomNum}`;

            // Create official voter record
            await prisma.voter.create({
                data: {
                    voterIdNumber,
                    fullName: app.fullName,
                    dateOfBirth: app.dateOfBirth,
                    gender: app.gender,
                    address: app.address,
                    pincode: app.pincode,
                    email: app.email,
                    mobile: app.mobile,
                },
            });

            // Update application status
            await prisma.voterApplication.update({
                where: { id: applicationId },
                data: { status: "APPROVED" },
            });

            // Create audit log
            await prisma.auditLog.create({
                data: {
                    applicationId,
                    action: "APPROVED",
                    performedBy: reviewer,
                    notes: `${notes} Official Voter ID ${voterIdNumber} generated.`,
                },
            });

            return { success: true, voterIdNumber };
        } else {
            // Rejection
            await prisma.voterApplication.update({
                where: { id: applicationId },
                data: { status: "REJECTED" },
            });

            await prisma.auditLog.create({
                data: {
                    applicationId,
                    action: "REJECTED",
                    performedBy: reviewer,
                    notes,
                },
            });

            return { success: true };
        }
    } catch (error) {
        console.error("Error reviewing application:", error);
        return { success: false, error: "Failed to process review decision." };
    }
}
